// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 _number,
        uint64 _ts,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _seq,
        bytes32 _batcherHash,
        uint256 _overhead,
        uint256 _scalar,
        uint256 warpTime
    ) public {
        vm.warp(bound(warpTime, 0, type(uint64).max));
        vm.prank(depositor);
        c.setL1BlockValues(_number, _ts, _basefee, _hash, _seq, _batcherHash, _overhead, _scalar);
        assertTrue(c.timestamp() == _ts);
    }
}
